"""민미 무기별 애니메이션(build_moomin.py 가 불러 씀) — 베개 방패(왼팔) · 회전 쌍검(오른손 hand.R + 왼팔 arm.L).
채널(키 목록 → 부드럽게 이어 매 프레임 키잉, 모든 큰 뼈를 매 프레임 키잉해 다른 클립의 자세가 남지 않게):
  hips: lean(앞 숙임 +) · spin(위에서 본 회전, + = 왼쪽으로 돎, 한 바퀴 이상도 OK) · up(m) · fwd(m) · side(m)
  arm.L / arm.R: lp/rp(앞으로 들기 −) · ly/ry(좌우 휘두르기, + = 몸 왼쪽으로) · lr/rr(옆으로 벌리기 — L 은 −, R 은 + 가 바깥)
  head: hp(숙임 +) · hy(도리) · 다리: llp/rlp(앞으로 −) · tail: tl
타격 프레임(HIT)은 Unity MoominSetup.WeaponHitFrames · SkillLibrary 의 hitTime(코인마다 hitTimes) 과 같아야 함."""
import math
from mathutils import Matrix, Vector, Euler

HIT = {"ShieldBash": (10, 24), "ShieldSwing": (10, 24), "ShieldSlam": (15, 30), "ShieldLeap": (22, 36),
       "DualSlash1": (10, 24), "DualSlash2": (10, 24), "DualCross": (10, 30), "DualDash": (10, 24), "DualWhirl": (10, 24), "DualGrind": (10, 20), "DualFinale": (26, 40)}
CH = ("lean", "spin", "up", "fwd", "side", "lp", "ly", "lr", "rp", "ry", "rr", "hp", "hy", "llp", "rlp", "tl")


def build(arm, new_action, key, finish_action, K):
    def RW(bone, pitch=0.0, yaw=0.0, roll=0.0):
        M = arm.data.bones[bone].matrix_local.to_3x3()
        W = Matrix.Rotation(yaw, 3, "Z") @ Matrix.Rotation(roll, 3, "Y") @ Matrix.Rotation(pitch, 3, "X")
        return (M.inverted() @ W @ M).to_euler()

    def track(keys):
        if not keys: return lambda f: 0.0
        keys = sorted(keys)
        def at(f):
            if f <= keys[0][0]: return keys[0][1]
            for (f0, v0), (f1, v1) in zip(keys, keys[1:]):
                if f <= f1:
                    u = (f - f0) / (f1 - f0) if f1 > f0 else 1.0; u = u * u * (3 - 2 * u); return v0 + (v1 - v0) * u
            return keys[-1][1]
        return at

    def clip(name, length, spec, loop=False):
        tr = {c: track(spec.get(c, [])) for c in CH}; act = new_action(arm, name, length)
        for f in range(1, length + 1):
            g = {c: tr[c](f) for c in CH}
            key(arm, "root", f)
            key(arm, "hips", f, rot=Euler((g["lean"], g["spin"], 0.0)), loc=Vector((g["side"], g["up"], g["fwd"])))   # hips 로컬 X = 세계 X, Y = 위, Z = 앞(-Y)
            key(arm, "head", f, rot=RW("head", g["hp"], g["hy"]))
            key(arm, "arm.L", f, rot=RW("arm.L", g["lp"], g["ly"], g["lr"])); key(arm, "arm.R", f, rot=RW("arm.R", g["rp"], g["ry"], g["rr"]))
            key(arm, "hand.R", f)
            key(arm, "leg.L", f, rot=RW("leg.L", g["llp"])); key(arm, "leg.R", f, rot=RW("leg.R", g["rlp"]))
            key(arm, "tail1", f, rot=RW("tail1", 0, g["tl"])); key(arm, "tail2", f)
            key(arm, "ear.L", f); key(arm, "ear.R", f)
        finish_action(arm, act, loop); act.frame_start, act.frame_end = 1, length
        return act


    A = {}
    # ══ 베개 방패(왼팔에 단 땅콩빵 방패 — 기본 자세에서 몸 앞 왼쪽을 향함)
    A["ShieldGuard"] = clip("ShieldGuard", 12, {"lp": [(1, 0), (6, -0.55), (12, -0.5)], "ly": [(1, 0), (6, -0.5), (12, -0.48)], "rp": [(1, 0), (6, -0.5), (12, -0.45)],
                                                 "lean": [(1, 0), (6, 0.12), (12, 0.1)], "up": [(1, 0), (6, -0.04), (12, -0.035)], "hp": [(1, 0), (6, 0.15), (12, 0.14)],
                                                 "llp": [(1, 0), (6, -0.25), (12, -0.22)], "rlp": [(1, 0), (6, 0.2), (12, 0.18)]}, loop=True)
    A["ShieldBash"] = clip("ShieldBash", 24, {"lp": [(1, 0), (6, 0.35), (10, -0.95), (16, -0.9), (24, 0)], "ly": [(1, 0), (6, 0.25), (10, -0.35), (16, -0.3), (24, 0)],
                                               "spin": [(1, 0), (6, 0.35), (10, -0.3), (16, -0.25), (24, 0)], "lean": [(1, 0), (6, -0.1), (10, 0.3), (16, 0.25), (24, 0)],
                                               "fwd": [(1, 0), (6, -0.03), (10, 0.16), (16, 0.14), (24, 0)], "up": [(1, 0), (6, -0.05), (10, 0), (24, 0)],
                                               "rp": [(1, 0), (6, 0.3), (10, 0.45), (24, 0)], "llp": [(1, 0), (10, -0.55), (16, -0.5), (24, 0)], "rlp": [(1, 0), (10, 0.45), (24, 0)],
                                               "hp": [(1, 0), (10, 0.12), (24, 0)], "tl": [(1, 0), (10, -0.5), (24, 0)]})
    A["ShieldSwing"] = clip("ShieldSwing", 24, {"lp": [(1, 0), (6, -0.9), (10, -1.05), (16, -1.0), (24, 0)], "ly": [(1, 0), (6, 0.95), (10, -0.85), (16, -1.0), (24, 0)],
                                                 "lr": [(1, 0), (6, -0.5), (10, 0), (24, 0)], "spin": [(1, 0), (6, 0.5), (10, -0.55), (16, -0.65), (24, 0)],
                                                 "lean": [(1, 0), (10, 0.15), (24, 0)], "rp": [(1, 0), (10, 0.3), (24, 0)], "rr": [(1, 0), (10, 0.4), (24, 0)],
                                                 "hy": [(1, 0), (6, 0.25), (10, -0.2), (24, 0)], "tl": [(1, 0), (6, -0.6), (10, 0.7), (24, 0)], "llp": [(1, 0), (10, -0.3), (24, 0)]})
    A["ShieldSlam"] = clip("ShieldSlam", 30, {"lp": [(1, 0), (9, -2.75), (13, -2.6), (15, -0.95), (22, -0.9), (30, 0)], "rp": [(1, 0), (9, -2.7), (13, -2.55), (15, -0.9), (22, -0.85), (30, 0)],
                                               "ly": [(1, 0), (9, -0.35), (15, -0.4), (30, 0)], "ry": [(1, 0), (9, 0.3), (15, 0.3), (30, 0)],
                                               "lean": [(1, 0), (9, -0.25), (13, -0.2), (15, 0.4), (22, 0.35), (30, 0)], "up": [(1, 0), (5, -0.05), (9, 0.13), (13, 0.1), (15, -0.07), (22, -0.06), (30, 0)],
                                               "hp": [(1, 0), (9, -0.2), (15, 0.25), (30, 0)], "llp": [(1, 0), (15, -0.35), (30, 0)], "rlp": [(1, 0), (15, -0.35), (30, 0)], "tl": [(1, 0), (15, 0.8), (30, 0)]})
    A["ShieldLeap"] = clip("ShieldLeap", 36, {"up": [(1, 0), (8, -0.09), (14, 0.55), (18, 0.6), (22, -0.06), (28, -0.05), (36, 0)], "fwd": [(1, 0), (8, 0), (18, 0.25), (22, 0.35), (36, 0)],
                                               "lp": [(1, 0), (8, 0.4), (14, -2.8), (18, -2.85), (22, -0.85), (28, -0.8), (36, 0)], "rp": [(1, 0), (8, 0.4), (14, -2.7), (18, -2.75), (22, -0.8), (28, -0.75), (36, 0)],
                                               "ly": [(1, 0), (18, -0.4), (22, -0.45), (36, 0)], "lean": [(1, 0), (8, 0.2), (14, -0.3), (18, -0.25), (22, 0.45), (28, 0.4), (36, 0)],
                                               "llp": [(1, 0), (8, -0.5), (14, 0.3), (18, -0.6), (22, -0.4), (36, 0)], "rlp": [(1, 0), (8, -0.5), (14, 0.3), (18, -0.6), (22, -0.4), (36, 0)],
                                               "hp": [(1, 0), (14, -0.25), (22, 0.3), (36, 0)], "tl": [(1, 0), (14, -0.6), (22, 0.9), (36, 0)]})
    # ══ 회전 쌍검(오른손·왼팔 끝에서 날이 바람개비처럼 돎 — 날 회전은 Unity WeaponSpin)
    G = {"lp": -1.45, "rp": -1.45, "ly": -0.22, "ry": 0.22, "lean": 0.3, "fwd": 0.06}   # 갈아 버리는 자세(두 날을 앞으로 모음)
    A["DualGuard"] = clip("DualGuard", 12, {"lp": [(1, 0), (6, -1.35), (12, -1.3)], "rp": [(1, 0), (6, -1.35), (12, -1.3)], "ly": [(1, 0), (6, -0.45), (12, -0.42)], "ry": [(1, 0), (6, 0.45), (12, 0.42)],
                                             "lean": [(1, 0), (6, 0.1), (12, 0.08)], "up": [(1, 0), (6, -0.04), (12, -0.035)], "hp": [(1, 0), (6, 0.12), (12, 0.1)],
                                             "llp": [(1, 0), (6, -0.25), (12, -0.22)], "rlp": [(1, 0), (6, 0.2), (12, 0.18)]}, loop=True)
    A["DualSlash1"] = clip("DualSlash1", 24, {"rp": [(1, 0), (5, -1.4), (10, -1.3), (15, -1.2), (24, 0)], "ry": [(1, 0), (5, -1.05), (10, 0.75), (15, 0.95), (24, 0)],
                                               "spin": [(1, 0), (5, -0.4), (10, 0.4), (15, 0.45), (24, 0)], "lp": [(1, 0), (10, -0.6), (24, 0)], "lean": [(1, 0), (10, 0.18), (24, 0)],
                                               "fwd": [(1, 0), (10, 0.08), (24, 0)], "rlp": [(1, 0), (10, -0.35), (24, 0)], "tl": [(1, 0), (5, 0.5), (10, -0.6), (24, 0)], "hy": [(1, 0), (5, -0.2), (10, 0.2), (24, 0)]})
    A["DualSlash2"] = clip("DualSlash2", 24, {"lp": [(1, 0), (5, -1.4), (10, -1.3), (15, -1.2), (24, 0)], "ly": [(1, 0), (5, 1.05), (10, -0.75), (15, -0.95), (24, 0)],
                                               "spin": [(1, 0), (5, 0.4), (10, -0.4), (15, -0.45), (24, 0)], "rp": [(1, 0), (10, -0.6), (24, 0)], "lean": [(1, 0), (10, 0.18), (24, 0)],
                                               "fwd": [(1, 0), (10, 0.08), (24, 0)], "llp": [(1, 0), (10, -0.35), (24, 0)], "tl": [(1, 0), (5, -0.5), (10, 0.6), (24, 0)], "hy": [(1, 0), (5, 0.2), (10, -0.2), (24, 0)]})
    A["DualCross"] = clip("DualCross", 30, {"rp": [(1, 0), (5, -2.1), (10, -1.0), (18, -0.95), (30, 0)], "ry": [(1, 0), (5, -0.75), (10, 0.55), (18, 0.6), (30, 0)],
                                             "lp": [(1, 0), (5, -2.1), (10, -1.0), (18, -0.95), (30, 0)], "ly": [(1, 0), (5, 0.75), (10, -0.55), (18, -0.6), (30, 0)],
                                             "lean": [(1, 0), (5, -0.15), (10, 0.3), (18, 0.28), (30, 0)], "up": [(1, 0), (5, 0.05), (10, -0.04), (30, 0)], "fwd": [(1, 0), (10, 0.1), (30, 0)],
                                             "hp": [(1, 0), (5, -0.15), (10, 0.2), (30, 0)], "llp": [(1, 0), (10, -0.4), (30, 0)], "rlp": [(1, 0), (10, 0.3), (30, 0)]})
    A["DualDash"] = clip("DualDash", 24, {"rp": [(1, 0), (6, -1.2), (10, -1.55), (16, -1.5), (24, 0)], "lp": [(1, 0), (6, -1.2), (10, -1.55), (16, -1.5), (24, 0)],
                                           "ry": [(1, 0), (10, 0.15), (24, 0)], "ly": [(1, 0), (10, -0.15), (24, 0)], "lean": [(1, 0), (6, 0.1), (10, 0.45), (16, 0.4), (24, 0)],
                                           "fwd": [(1, 0), (6, -0.03), (10, 0.2), (16, 0.18), (24, 0)], "up": [(1, 0), (6, -0.05), (10, -0.02), (24, 0)],
                                           "llp": [(1, 0), (10, 0.5), (24, 0)], "rlp": [(1, 0), (10, -0.65), (24, 0)], "tl": [(1, 0), (10, 0.7), (24, 0)]})
    A["DualWhirl"] = clip("DualWhirl", 24, {"spin": [(1, 0), (3, -0.3), (14, 2 * math.pi), (24, 2 * math.pi)], "lr": [(1, 0), (4, -1.45), (14, -1.45), (24, 0)], "rr": [(1, 0), (4, 1.45), (14, 1.45), (24, 0)],
                                             "lp": [(1, 0), (4, -0.3), (14, -0.3), (24, 0)], "rp": [(1, 0), (4, -0.3), (14, -0.3), (24, 0)], "up": [(1, 0), (6, 0.08), (10, 0.06), (14, 0), (24, 0)],
                                             "lean": [(1, 0), (10, 0.12), (24, 0)], "tl": [(1, 0), (6, 1.0), (14, 0.8), (24, 0)], "hp": [(1, 0), (10, 0.1), (24, 0)]})
    jit = lambda a, n=20: [(1, 0)] + [(1 + k * (n - 1) // 8, a * (1 if k % 2 else -1)) for k in range(1, 8)] + [(n, 0)]
    A["DualGrind"] = clip("DualGrind", 20, {"lp": [(1, G["lp"]), (10, G["lp"] - 0.1), (20, G["lp"])], "rp": [(1, G["rp"]), (10, G["rp"] - 0.1), (20, G["rp"])],
                                             "ly": [(1, G["ly"]), (20, G["ly"])], "ry": [(1, G["ry"]), (20, G["ry"])], "lean": [(1, G["lean"]), (10, G["lean"] + 0.06), (20, G["lean"])],
                                             "fwd": [(1, G["fwd"]), (10, G["fwd"] + 0.05), (20, G["fwd"])], "spin": jit(0.07), "side": jit(0.012), "up": [(1, -0.03), (20, -0.03)],
                                             "llp": [(1, -0.35), (20, -0.35)], "rlp": [(1, 0.3), (20, 0.3)], "hp": [(1, 0.1), (20, 0.1)], "tl": jit(0.35)}, loop=False)
    A["DualFinale"] = clip("DualFinale", 40, {"lp": [(1, G["lp"]), (8, -0.25), (14, -2.8), (22, -2.85), (26, -0.75), (32, -0.7), (40, 0)], "rp": [(1, G["rp"]), (8, -0.25), (14, -2.8), (22, -2.85), (26, -0.75), (32, -0.7), (40, 0)],
                                               "ly": [(1, G["ly"]), (14, 0), (26, -0.3), (40, 0)], "ry": [(1, G["ry"]), (14, 0), (26, 0.3), (40, 0)],
                                               "up": [(1, -0.03), (8, -0.1), (14, 0.7), (21, 0.75), (26, -0.07), (32, -0.06), (40, 0)], "fwd": [(1, G["fwd"]), (14, 0.15), (26, 0.4), (40, 0)],
                                               "spin": [(1, 0), (12, 0), (22, 2 * math.pi), (40, 2 * math.pi)], "lean": [(1, G["lean"]), (8, 0.25), (14, -0.3), (22, -0.2), (26, 0.5), (32, 0.45), (40, 0)],
                                               "llp": [(1, -0.35), (8, -0.6), (14, 0.3), (22, -0.6), (26, -0.45), (40, 0)], "rlp": [(1, 0.3), (8, -0.6), (14, 0.3), (22, -0.6), (26, -0.45), (40, 0)],
                                               "hp": [(1, 0.1), (14, -0.3), (26, 0.3), (40, 0)], "tl": [(1, 0), (14, -0.8), (26, 1.0), (40, 0)]})
    return A
